25		<meta name="twitter:description" content="A well-structured, accessible HTML5 document with modern best practices.">
26		<meta name="twitter:image" content="https://example.com/og-image.png">
27		<style>
28			:root {
29				color-scheme: light dark;
30				--text: #1a1a1a;
31				--text-secondary: #555;
32				--background: #fff;
33				--accent: #0052a3;
34				--border: #e0e0e0;
35			}
36			@media (prefers-color-scheme: dark) {
37				:root {
38					--text: #e0e0e0;
39					--text-secondary: #a0a0a0;
40					--background: #121212;
41					--accent: #5fa3ff;
42					--border: #333;
43				}
44			}
45			*,
46			*::before,
47			*::after {
48				box-sizing: border-box;
49			}
50			html {
51				-webkit-text-size-adjust: 100%;
52				text-size-adjust: 100%;
53			}
54			@media (prefers-reduced-motion: no-preference) {
55				html {
56					scroll-behavior: smooth;
57				}
58				a {
59					transition: text-decoration-thickness 0.15s ease;
60				}
61				.skip-link {
62					transition: transform 0.15s ease;
63				}
64			}
65			body {
66				display: grid;
67				grid-template-rows: auto 1fr auto;
68				min-height: 100vh;
69				min-height: 100dvh;
70				font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
71				font-size: 1rem;
72				line-height: 1.6;
73				max-width: 70ch;
74				margin: 0 auto;
75				padding: clamp(1rem, 5vw, 1.5rem);
76				padding-top: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-top));
77				padding-right: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-right));
78				padding-bottom: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-bottom));
79				padding-left: max(clamp(1rem, 5vw, 1.5rem), env(safe-area-inset-left));
80				color: var(--text);
81				background: var(--background);
82			}
83			h1 {
84				color: var(--accent);
85				font-size: clamp(1.75rem, 1.25rem + 3vw, 2.5rem);
86				font-weight: 700;
87				line-height: 1.1;
88				text-wrap: balance;
89				margin: 0 0 1.5rem 0;
90				letter-spacing: -0.02em;
91			}
92			p {
93				text-wrap: pretty;
94				margin: 1rem 0;
95			}
96			a {
97				color: var(--accent);
98				text-underline-offset: 0.2em;
99				text-decoration-thickness: 2px;
100				text-decoration-skip-ink: auto;
101				font-weight: 500;
102			}
103			a:hover, a:active {
104				text-decoration-thickness: 3px;
105			}
106			:focus-visible {
107				outline: 2px solid var(--accent);
108				outline-offset: 2px;
109				border-radius: 2px;
110			}
111			button:focus-visible, a:focus-visible {
112				box-shadow: 0 0 0 3px var(--background), 0 0 0 5px var(--accent);
113				outline: none;
114			}
115			.skip-link {
116				position: absolute;
117				left: 0;
118				top: 0;
119				transform: translateY(-100%);
120				background: var(--accent);
121				color: var(--background);
122				padding: 0.75rem 1.5rem;
123				z-index: 1000;
124				border-radius: 0 0 0.25rem 0;
125				font-weight: 600;
126				text-decoration: none;
127				display: inline-block;
128			}
129			.skip-link:focus {
130				transform: none;
131				outline: 3px solid var(--text);
132				outline-offset: -3px;
133			}
134			header {
135				padding-block: 1.5rem 0;
136			}
137			main {
138				padding: 1rem 0;
139			}
140			main:focus {
141				outline: none;
142			}
143			footer {
144				padding-block: 1.5rem;
145				margin-top: 3rem;
146				border-top: 1px solid var(--border);
147				font-size: 0.875rem;
148				color: var(--text-secondary);
149				text-align: center;
150			}
151			footer p {
152				margin: 0.5rem 0;
153			}
154			@media print {
155				.skip-link {
156					display: none;
157				}
158				body {
159					display: block;
160					min-height: 0;
161					max-width: none;
162					padding: 0;
163				}
164				a {
165					color: inherit;
166					text-decoration: underline;
167				}
168				a[href^="http"]::after {
169					content: " (" attr(href) ")";
170					font-size: 0.85em;
171					font-weight: normal;
172				}
173			}
174		</style>
175	</head>
176	<body>
177		<a class="skip-link" href="#main">Skip to content</a>
178		<header>
179			<h1>Welcome</h1>
180		</header>
181		<main id="main" tabindex="-1">
182			<p>This is a well-structured, accessible HTML5 document.</p>
183			<p>
184				It uses semantic landmarks, a skip link for keyboard navigation,
185				and CSS that adapts to your light or dark mode preference.
186			</p>
187			<p>
188				Text and link colors meet WCAG AA contrast in both themes, type scales
189				with your browser's font size, and motion respects your system settings.
190			</p>
191		</main>
192		<footer>
193			<p><small>&copy; <time datetime="2026">2026</time>. All rights reserved.</small></p>
194		</footer>
195	</body>
196	</html>
